oxy_webhelp_navlinks = {"mv_managed_volumes_sla_managed_volumes-d39536e49164":{"topics":[{"title":"Introduction to Managed Volumes and SLA Managed Volumes protection","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects host application data using Managed\n                    Volumes and SLA Managed Volumes, providing network-attached backup targets\n                    on a Rubrik cluster with SLA Domain-driven snapshot management.<\/p>","href":"managedvolumes\/mv_protection_key_features.html","menu":{"hasChildren":false},"tocID":"tocId-d39536e49177","next":"tocId-d39536e49177"},{"title":"Managed Volumes and SLA Managed Volumes protection implementation workflow","shortdesc":"<p class=\"shortdesc\">A high-level workflow that outlines the phases for implementing Managed Volumes and         SLA Managed Volumes protection in <span class=\"ph\">RSC<\/span>.<\/p>","href":"managedvolumes\/mv_high_level_implementation.html","attributes":{"data-id":"mv_high_level_implementation"},"menu":{"hasChildren":false},"tocID":"mv_high_level_implementation-d39536e49235","topics":[]},{"title":"Quick links for Managed Volumes and SLA Managed Volumes","shortdesc":"<p class=\"shortdesc\">Immediate access to important tasks and information, enabling quick setup, daily         operations, and critical recovery.<\/p>","href":"managedvolumes\/mv_quick_links.html","attributes":{"data-id":"mv_quick_links"},"menu":{"hasChildren":false},"tocID":"mv_quick_links-d39536e49249","topics":[]},{"title":"Plan your Managed Volumes and SLA Managed Volumes protection","shortdesc":"<p class=\"shortdesc\">Before setting up Managed Volumes and SLA Managed Volumes in <span class=\"ph\">RSC<\/span>,         review the host setup requirements, channel creation guidelines, network configuration, and         protection limitations.<\/p>","href":"managedvolumes\/mv_plan_protection.html","attributes":{"data-id":"mv_plan_protection"},"menu":{"hasChildren":false},"tocID":"mv_plan_protection-d39536e49260","next":"mv_plan_protection-d39536e49260"},{"title":"Set up your Managed Volumes and SLA Managed Volumes","shortdesc":"<p class=\"shortdesc\">You can set up floating IP addresses on the Rubrik cluster and configure Managed         Volumes and SLA Managed Volumes for hosts to write backup data into the volumes.<\/p>","href":"managedvolumes\/mv_set_up_managed_volumes.html","attributes":{"data-id":"mv_set_up_managed_volumes"},"menu":{"hasChildren":false},"tocID":"mv_set_up_managed_volumes-d39536e49346","next":"mv_set_up_managed_volumes-d39536e49346"},{"title":"Set up your Managed Volumes and SLA Managed Volumes protection","shortdesc":"<p class=\"shortdesc\">You can configure backup script settings for SLA Managed Volumes, define custom SLA         Domains, and assign SLA Domains to Managed Volumes and SLA Managed Volumes to         protect the backup data that hosts write         into them.<\/p>","href":"managedvolumes\/mv_set_up_protection.html","attributes":{"data-id":"mv_set_up_protection"},"menu":{"hasChildren":false},"tocID":"mv_set_up_protection-d39536e49459","next":"mv_set_up_protection-d39536e49459"},{"title":"Manage Managed Volumes and SLA Managed Volumes snapshots","shortdesc":"<p class=\"shortdesc\">You can monitor Managed Volumes and SLA Managed Volumes, take on-demand snapshots,         place legal holds, change retention policies, and delete snapshots when they are no longer         needed.<\/p>","href":"managedvolumes\/mv_manage_snapshots.html","attributes":{"data-id":"mv_manage_snapshots"},"menu":{"hasChildren":false},"tocID":"mv_manage_snapshots-d39536e49514","next":"mv_manage_snapshots-d39536e49514"},{"title":"Recover Managed Volumes and SLA Managed Volumes","shortdesc":"<p class=\"shortdesc\">You can recover files and folders from a Managed Volume and an SLA Managed Volume         snapshot, or you can create a Live Mount of a Managed Volume or SLA Managed Volume snapshot         for in-place recovery.<\/p>","href":"managedvolumes\/mv_recover.html","attributes":{"data-id":"mv_recover"},"menu":{"hasChildren":false},"tocID":"mv_recover-d39536e49660","next":"mv_recover-d39536e49660"}]}};